#include <stdio.h>

int fib(int n) {
    if(n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}

int main() {
    printf("%d", fib(10));
}

#include <stdio.h>

typedef struct {
    int id;
    int score;
} Student;

void addBonus(Student *s, int n, int bonus) {
    for (int i = 0; i < n; i++) {
        s[i].score += bonus;
    }
}

int main() {
    Student list[3] = {{1, 70}, {2, 80}, {3, 90}};
    addBonus(list, 3, 5);
    int total = 0;
    for (int i = 0; i < 3; i++) {
        total += list[i].score;
    }
    printf("%d", total);
    return 0;
}

