public class main {
    public static void main(String[] args) {
        Base obj = new Derived();
        obj.show();
        obj.display();
    }
}

class Base {
    static void display() {
        System.out.print("Base-static");
    }
    void show() {
        System.out.print("Base-show");
    }
}

class Derived extends Base {
    static void display() {
        System.out.print("Derived-static");
    }
    void show() {
        System.out.print("Derived-show");
    }
}
